//! Phase G courts: exhaustive inverse proceduralization.
//!
//! Each court is a **raster-origin** sequence (frames generated by an
//! independent deterministic generator — never by the encoder) that is pushed
//! through `inverse::encode_frames`, whose exhaustive per-frame candidate
//! space is: UNCHANGED · FILL · CLEAR-ONLY · EXACT_OBJECT_REF · RAW · SPARSE
//! (persistent overlay commit) · one-shot RESIDUAL / RANS_RESIDUAL · COPY_RECT
//! (wrap, screen-scroll, prev-diff composites) · TRANSLATION.
//!
//! Every emitted stream must decode with the normative decoder to byte-
//! identical rasters (`report.exact`); the winning family per frame must be
//! the measured low-cost explanation for the court's content; and the oracle
//! records (winner == min over every evaluated family) must be consistent.
//! The noise negative control proves RAW fallback with bounded overhead.

use vole_video::{
    error::VoleError,
    inverse::{self, EncodeOptions, SearchSpace},
    pixel::Canvas,
};

/// Deterministic xorshift64* byte source.
struct Det(u64);
impl Det {
    fn next(&mut self) -> u64 {
        let mut x = self.0.max(1);
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        x = x.wrapping_mul(0x2545_F491_4F6C_DD1D);
        self.0 = x;
        x
    }
    fn byte(&mut self) -> u8 {
        (self.next() >> 56) as u8
    }
}

fn canvas_of(w: u32, h: u32, data: Vec<u8>) -> Canvas {
    Canvas::from_parts(w, h, data).expect("canvas")
}

fn uniform(w: u32, h: u32, v: u8) -> Canvas {
    canvas_of(w, h, vec![v; (w * h) as usize])
}

/// Independent painter: clear to `bg`, then blit boxes in paint order.
fn paint_boxes(w: u32, h: u32, bg: u8, boxes: &[(i64, i64, u32, u32, u8)]) -> Canvas {
    let mut data = vec![bg; (w * h) as usize];
    for (bx, by, bw, bh, v) in boxes {
        for dy in 0..*bh as i64 {
            for dx in 0..*bw as i64 {
                let x = bx + dx;
                let y = by + dy;
                if x >= 0 && y >= 0 && x < i64::from(w) && y < i64::from(h) {
                    data[y as usize * w as usize + x as usize] = *v;
                }
            }
        }
    }
    canvas_of(w, h, data)
}

fn no_sweep() -> EncodeOptions {
    EncodeOptions {
        bg_sweep: false,
        ..EncodeOptions::default()
    }
}

